long long nCr(int n, int r) {
    if (r < 0 || r > n) return 0;
    r = min(r, n - r);                 // symmetry keeps the loop short
    long long result = 1;
    for (int i = 0; i < r; i++)
        result = result * (n - i) / (i + 1);
    return result;
}

