function nCr(n, r) {
  if (r < 0 || r > n) return 0;
  r = Math.min(r, n - r);              // symmetry keeps the loop short
  let result = 1;
  for (let i = 0; i < r; i++)
    result = (result * (n - i)) / (i + 1);
  return result;
}
